import unittest
from candidate import circular_shift

class TestCircularShift(unittest.TestCase):
    def test_normal_shift_one_digit(self):
        self.assertEqual(circular_shift(1, 1), "1")

    def test_normal_shift_two_digits(self):
        self.assertEqual(circular_shift(12, 1), "21")

    def test_normal_shift_three_digits(self):
        self.assertEqual(circular_shift(123, 1), "312")

    def test_normal_shift_larger_shift_than_length(self):
        self.assertEqual(circular_shift(123, 3), "321")

    def test_shift_equal_to_length(self):
        self.assertEqual(circular_shift(123, 3), "321")

    def test_shift_greater_than_length(self):
        self.assertEqual(circular_shift(12345, 6), "54321")

    def test_shift_exactly_one_digit(self):
        self.assertEqual(circular_shift(1234, 1), "4123")

    def test_empty_string_behavior(self):
        with self.assertRaises(TypeError):
            circular_shift("", 1)

    def test_none_input(self):
        with self.assertRaises(TypeError):
            circular_shift(None, 1)

    def test_negative_number(self):
        self.assertEqual(circular_shift(-123, 2), "3-12")

    def test_single_negative_digit(self):
        self.assertEqual(circular_shift(-1, 1), "-1")

    def test_zero_input(self):
        self.assertEqual(circular_shift(0, 1), "0")

    def test_shift_zero(self):
        self.assertEqual(circular_shift(12345, 0), "12345")

    def test_non_integer_shift(self):
        with self.assertRaises(TypeError):
            circular_shift(123, "1")

    def test_non_integer_input(self):
        with self.assertRaises(TypeError):
            circular_shift("123", 1)

    def test_large_number(self):
        self.assertEqual(circular_shift(123456789, 5), "789123456")

    def test_reverse_behavior(self):
        self.assertEqual(circular_shift(12345, 7), "54321")

    def test_mixed_positive_negative_shift(self):
        self.assertEqual(circular_shift(123, -1), "312")

    def test_leading_zeros_in_reversed(self):
        self.assertEqual(circular_shift(1000, 4), "0001")

    def test_leading_zeros_in_shifted(self):
        self.assertEqual(circular_shift(1000, 1), "0100")
